Definition shx (o : Z) : expr :=
  EAlu ALU_AND (EAlu ALU_ADD (EAlu ALU_SRL (EAlu ALU_ADD (EVar 0) (ELit o)) (ELit 3)) (ELit 2147450880)) (ELit (-8)).
Definition shw (spz o : Z) : Z := (8 * (((spz + o) / 8 + 2147450880) / 8))%Z.

