Fixpoint outside_zb (a : Z) (w : Z) (rs : list (Z * Z)) : bool :=
  match rs with
  | [] => true
  | (lo, len) :: r => ((a + w <=? lo) || (lo + len <=? a))%Z && outside_zb a w r
  end.
